use std::fs

fn is_leap(y: int) -> bool {
    (y % 4 == 0 && y % 100 != 0) || y % 400 == 0
}

fn days_in_month(y: int, m: int) -> int {
    if m == 2 {
        if is_leap(y) { 29 } else { 28 }
    } else if m == 4 || m == 6 || m == 9 || m == 11 {
        30
    } else {
        31
    }
}

// days since 1970-01-01, or -999999999 if invalid
fn parse_date(s: string) -> int {
    let cs: Vec<char> = s.chars().collect()
    if cs.len() != 10 {
        return -999999999
    }
    let mut digits: Vec<int> = []
    let mut i = 0
    while i < 10 {
        let c = cs[i]
        if i == 4 || i == 7 {
            if c != '-' {
                return -999999999
            }
        } else {
            if c < '0' || c > '9' {
                return -999999999
            }
            digits.push((c as int) - 48)
        }
        i += 1
    }
    let y = digits[0] * 1000 + digits[1] * 100 + digits[2] * 10 + digits[3]
    let m = digits[4] * 10 + digits[5]
    let d = digits[6] * 10 + digits[7]
    if m < 1 || m > 12 || d < 1 || d > days_in_month(y, m) {
        return -999999999
    }
    let yy = if m <= 2 { y - 1 } else { y }
    let era = yy / 400
    let yoe = yy - era * 400
    let mp = (m + 9) % 12
    let doy = (153 * mp + 2) / 5 + d - 1
    let doe = yoe * 365 + yoe / 4 - yoe / 100 + doy
    era * 146097 + doe - 719468
}

fn main() {
    let names = ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"]
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    for line in text.lines() {
        let t = line.trim()
        if t.len() == 0 {
            continue
        }
        let parts: Vec<string> = t.split_whitespace().collect()
        if parts.len() != 2 {
            println("invalid")
            continue
        }
        let a = parse_date(parts[0])
        let b = parse_date(parts[1])
        if a == -999999999 || b == -999999999 {
            println("invalid")
            continue
        }
        let lo = if a < b { a } else { b }
        let hi = if a < b { b } else { a }
        let w = ((lo + 3) % 7 + 7) % 7
        println("${hi - lo} ${names[w as usize]}")
    }
}

